insert into public.scenario_screen_translations (screen_id, locale, text) values ('b1000163-0000-0000-0009-000000000163', 'fr', 'Moi aussi, je fais de la pâtisserie, en fait. J’ai fait des cookies aux pépites de chocolat…')
